"""Small dense strictly convex QP solver.

    minimise  0.5 x' Q x + q' x
    subject to  C x  = d   (rows flagged in ``eq``)
                C x <= d   (other rows)
                x >= 0

Q is symmetric positive definite, the rows of C have pairwise disjoint
supports (one block of variables per row), so every working-set KKT system
is quasi-definite and non-singular while the working set stays consistent.

The solver is a classical primal active-set iteration that keeps a feasible
iterate, followed by an exact polish of the final working set and a full
KKT verification.  A repair loop is used as a fallback.
"""
import numpy as np

__all__ = ["solve_qp", "equality_qp", "kkt_residual"]


def _solve(K, rhs):
    """Linear solve with lstsq fallback and iterative refinement."""
    sol = None
    try:
        sol = np.linalg.solve(K, rhs)
    except np.linalg.LinAlgError:
        sol = None
    if sol is None or not np.all(np.isfinite(sol)):
        sol = np.linalg.lstsq(K, rhs, rcond=None)[0]
    if sol is None or not np.all(np.isfinite(sol)):
        return None
    for _ in range(2):
        try:
            res = rhs - np.asarray(K @ sol)
        except Exception:
            break
        if not np.all(np.isfinite(res)):
            break
        try:
            cor = np.linalg.solve(K, res)
        except np.linalg.LinAlgError:
            break
        if cor is None or not np.all(np.isfinite(cor)):
            break
        sol = sol + cor
    return sol


def equality_qp(Q, q, C, d, keep, tight):
    """min .5x'Qx+q'x with x_i=0 for i not in ``keep`` and C[tight]x=d[tight].

    Returns (x, lam) with lam zero outside ``tight``.
    """
    n = int(q.shape[0])
    m = int(d.shape[0])
    x = np.zeros(n)
    lam = np.zeros(m)
    keep = list(keep)
    tight = list(tight)
    ns = len(keep)
    nt = len(tight)
    if ns == 0:
        return x, lam
    Qs = Q[np.ix_(keep, keep)]
    if nt == 0:
        sol = _solve(Qs, -q[keep])
        if sol is None:
            return x, lam
        x[keep] = sol
        return x, lam
    Cs = C[np.ix_(tight, keep)]
    size = ns + nt
    K = np.zeros((size, size))
    K[:ns, :ns] = Qs
    K[:ns, ns:] = Cs.T
    K[ns:, :ns] = Cs
    rhs = np.concatenate([-q[keep], d[tight]])
    sol = _solve(K, rhs)
    if sol is None:
        return x, lam
    x[keep] = sol[:ns]
    lam[tight] = sol[ns:]
    return x, lam


def kkt_residual(Q, q, C, d, eq, x, lam, keep, tight):
    """Worst violation of the KKT conditions (positive = violation)."""
    n = int(q.shape[0])
    m = int(d.shape[0])
    worst = 0.0
    if n:
        scale = max(1.0, float(np.abs(x).max()))
        worst = max(worst, float(-min(0.0, x.min())) / scale)
    g = Q @ x + q if n else np.zeros(0)
    if n:
        nu = g + (C.T @ lam if m else 0.0)
        for i in range(n):
            if i in keep:
                continue
            if nu[i] < 0.0:
                worst = max(worst, float(-nu[i]) / max(1.0, abs(float(nu[i]))))
    if m:
        for k in range(m):
            if k in tight:
                if not eq[k] and lam[k] < 0.0:
                    worst = max(worst, float(-lam[k]) / max(1.0, abs(float(lam[k]))))
            else:
                slack = float(C[k] @ x) - float(d[k])
                if slack > 0.0:
                    worst = max(worst, slack / max(1.0, abs(float(d[k]))))
    # working set consistency
    if m:
        for k in tight:
            resid = float(C[k] @ x) - float(d[k])
            worst = max(worst, abs(resid) / max(1.0, abs(float(d[k]))))
    return worst


def _active_set(Q, q, C, d, eq, x0, max_iter):
    n = int(q.shape[0])
    m = int(d.shape[0])
    x = np.array(x0, dtype=float)
    keep = set(i for i in range(n) if x[i] > 0.0)
    tight = set(k for k in range(m) if eq[k])
    for k in range(m):
        if not eq[k] and float(C[k] @ x) >= float(d[k]) - 0.0:
            tight.add(k)
    for i in range(n):
        if i not in keep:
            x[i] = 0.0
    dtol = 1e-11
    for _ in range(max_iter):
        free = sorted(keep)
        ts = sorted(tight)
        xstar, lam = equality_qp(Q, q, C, d, free, ts)
        p = xstar - x
        pn = float(np.abs(p).max()) if n else 0.0
        ptol = 1e-12 * max(1.0, float(np.abs(xstar).max()) if n else 1.0)
        if pn <= ptol:
            x = xstar
            g = Q @ xstar + q
            nu = g + (C.T @ lam if m else 0.0)
            worst = None
            for i in range(n):
                if i in keep:
                    continue
                if nu[i] < -dtol and (worst is None or nu[i] < worst[0]):
                    worst = (nu[i], "b", i)
            for k in ts:
                if eq[k]:
                    continue
                if lam[k] < -dtol and (worst is None or lam[k] < worst[0]):
                    worst = (lam[k], "c", k)
            if worst is None:
                return x, lam, keep, tight, True
            if worst[1] == "b":
                keep.discard(worst[2])
            else:
                tight.discard(worst[2])
            continue
        alpha = 1.0
        block = None
        for i in free:
            if p[i] < 0.0:
                a = -x[i] / p[i]
                if a < alpha:
                    alpha = a
                    block = ("b", i)
        if m:
            Cx = C @ x
            Cp = C @ p
            for k in range(m):
                if eq[k] or k in tight:
                    continue
                if Cp[k] > 0.0:
                    a = (float(d[k]) - float(Cx[k])) / float(Cp[k])
                    if a < alpha:
                        alpha = a
                        block = ("c", k)
        if alpha < 0.0:
            alpha = 0.0
        x = x + alpha * p
        for i in range(n):
            if i not in keep:
                x[i] = 0.0
        if block is not None:
            if block[0] == "b":
                keep.discard(block[1])
                x[block[1]] = 0.0
            else:
                tight.add(block[1])
    free = sorted(keep)
    ts = sorted(tight)
    xstar, lam = equality_qp(Q, q, C, d, free, ts)
    return xstar, lam, keep, tight, False


def _repair(Q, q, C, d, eq, keep, tight, max_iter):
    """Dual-style repair loop seeded with a working-set guess."""
    n = int(q.shape[0])
    m = int(d.shape[0])
    keep = set(keep)
    tight = set(tight)
    tabu = {}
    best = None
    for it in range(max_iter):
        free = sorted(keep)
        ts = sorted(tight)
        x, lam = equality_qp(Q, q, C, d, free, ts)
        resid = kkt_residual(Q, q, C, d, eq, x, lam, keep, tight)
        if best is None or resid < best[0]:
            best = (resid, x.copy(), lam.copy())
        if resid <= 1e-9:
            return x, lam, keep, tight, True
        # primal violations first
        cand = []
        for i in free:
            if x[i] < -1e-12 * max(1.0, abs(float(x[i]))):
                cand.append((float(-x[i]), 0, "drop", i))
        if m:
            for k in range(m):
                if eq[k] or k in tight:
                    continue
                slack = float(C[k] @ x) - float(d[k])
                if slack > 1e-12 * max(1.0, abs(float(d[k]))):
                    cand.append((slack, 1, "tighten", k))
        if not cand:
            g = Q @ x + q if n else np.zeros(0)
            nu = g + (C.T @ lam if m else 0.0)
            for i in range(n):
                if i in keep:
                    continue
                if tabu.get(i, -1) > it:
                    continue
                if nu[i] < -1e-12:
                    cand.append((float(-nu[i]), 2, "free", i))
            for k in ts:
                if eq[k]:
                    continue
                if lam[k] < -1e-12:
                    cand.append((float(-lam[k]), 3, "loosen", k))
        if not cand:
            break
        cand.sort(key=lambda t: (-t[0], t[1]))
        _, _, action, idx = cand[0]
        if action == "drop":
            keep.discard(idx)
            tabu[idx] = it + 5
        elif action == "tighten":
            tight.add(idx)
        elif action == "free":
            keep.add(idx)
        else:
            tight.discard(idx)
    if best is None:
        return np.zeros(n), np.zeros(m), keep, tight, False
    return best[1], best[2], keep, tight, best[0] <= 1e-9


def solve_qp(Q, q, C, d, eq, x0):
    """Return (x, lam, ok)."""
    n = int(q.shape[0])
    m = int(d.shape[0])
    if n == 0:
        return np.zeros(0), np.zeros(m), True
    Q = np.asarray(Q, dtype=float)
    q = np.asarray(q, dtype=float)
    if m:
        C = np.asarray(C, dtype=float).reshape(m, n)
        d = np.asarray(d, dtype=float).reshape(m)
        eq = list(eq)
    else:
        C = np.zeros((0, n))
        d = np.zeros(0)
        eq = []
    limit = 40 + 12 * (n + m)
    x, lam, keep, tight, ok = _active_set(Q, q, C, d, eq, x0, limit)
    if ok:
        x = np.maximum(x, 0.0)
        if kkt_residual(Q, q, C, d, eq, x, lam, keep, tight) <= 1e-8:
            return x, lam, True
    # fallbacks seeded from the active-set working set
    seeds = [(set(keep), set(tight))]
    seeds.append((set(i for i in range(n) if x[i] > 0.0), set(tight)))
    seeds.append((set(range(n)), set(k for k in range(m) if eq[k])))
    x0u = np.array(x0, dtype=float)
    seeds.append((set(i for i in range(n) if x0u[i] > 0.0),
                  set(k for k in range(m) if eq[k])))
    best = None
    for sk, st in seeds:
        xr, lamr, kr, tr, okr = _repair(Q, q, C, d, eq, sk, st, 300)
        xr = np.maximum(xr, 0.0)
        resid = kkt_residual(Q, q, C, d, eq, xr, lamr, kr, tr)
        if best is None or resid < best[0]:
            best = (resid, xr, lamr)
        if okr and resid <= 1e-9:
            return xr, lamr, True
    if best is not None and best[0] <= 1e-8:
        return best[1], best[2], True
    if best is not None:
        return best[1], best[2], False
    return x, lam, False
PYEOF
